```sql
CREATE TABLE users (
  id UUID PRIMARY KEY, email TEXT UNIQUE NOT NULL,
  password_hash TEXT, created_at TIMESTAMP DEFAULT NOW()
);

CREATE TABLE products (
  id UUID PRIMARY KEY, seller_id UUID REFERENCES users(id),
  name TEXT NOT NULL, description TEXT,
  price_cents INTEGER NOT NULL, stock INTEGER DEFAULT 0,
  category_id UUID REFERENCES categories(id),
  created_at TIMESTAMP DEFAULT NOW()
);

CREATE TABLE orders (
  id UUID PRIMARY KEY, buyer_id UUID REFERENCES users(id),
  total_cents INTEGER NOT NULL,
  status TEXT DEFAULT 'pending', created_at TIMESTAMP DEFAULT NOW()
);

CREATE TABLE order_items (
  id UUID PRIMARY KEY, order_id UUID REFERENCES orders(id),
  product_id UUID REFERENCES products(id),
  quantity INTEGER NOT NULL, price_cents INTEGER NOT NULL
);

CREATE TABLE categories (
  id UUID PRIMARY KEY, parent_id UUID REFERENCES categories(id), name TEXT NOT NULL
);

CREATE INDEX idx_products_category ON products(category_id);
CREATE INDEX idx_orders_buyer ON orders(buyer_id);
```

